mapper.select:
select b.work_proc_id
from   TB_WORK_ORDER_BATCH a
           inner join TB_WORK_ORDER_PROC b
                      on b.proc_cd = #{procCd}
                          and  b.work_batch_id = a.work_batch_id
where  a.work_batch_id = #{workBatchId}

mapper.update:
update TB_WORK_ORDER_PROC
set    proc_status          = #{procStatus}
      ,storage_cd           = #{storageCd}
      ,work_equipment_Cd    = #{workEquipmentCd}
      ,prod_date            = convert(date, getdate(), -23)
      ,work_start_time      = getDate()
      ,test_no              = #{testNo}
      ,upd_id               = #{userId}
      ,upd_dt               = getDate()
where  work_proc_id         = #{workProcId}

update TB_WORK_ORDER_PROC
set    proc_status      = #{procStatus}
      ,in_tran_id       = #{inTranId}
      ,work_end_time    = getDate()
      ,upd_id           = #{userId}
      ,upd_dt           = getDate()
where  work_proc_id     = #{workProcId}

update TB_WORK_ORDER_PROC
set    prod_qty      = #{prodQty}
      ,etc           = #{etc}
      ,upd_id        = #{userId}
      ,upd_dt        = getDate()
where  work_proc_id  = #{workProcId}

update tb_weigh_info
set    maker       = #{maker}
      ,make_Qty    = #{makeQty}
      ,upd_id      = #{userId}
      ,upd_dt      = getDate()
where  weigh_id    = #{weighId}

update tb_weigh_info
set    make_yn ='Y'
where  weigh_id = #{weighId}

update tb_make_etc
set    bom_ver  =  #{bomVer}
      ,maker    = #{maker}
      ,confirmer = #{confirmer}
      ,process_Time = #{processTime}
      ,mat_Proc = #{matProc}
      ,manipulate = #{manipulate}
      ,significant = #{significant}
      ,note     = #{note}
      ,filter_cnt = #{filterCnt}
      ,filter_Type = #{filterType}
      ,filter_Damage = #{filterDamage}
      ,substance_check = #{substanceCheck}
      ,upd_id  = #{userId}
      ,upd_dt = getDate()
where  work_proc_id = #{workProcId}

update TB_WORK_ORDER_PROC
set    proc_status = #{procStatus}
      ,work_end_time = getDate()
      ,tran_yn      = 'Y'
      ,tran_id       = #{tranId}
      ,upd_id       = #{userId}
      ,upd_dt       = getdate()
where  work_proc_id = #{workProcId}

mapper.select:
select CONCAT(CONVERT(varchar(10),c.work_order_date,23),' - ',c.seq) AS workOrderDateSeq ,dbo.getCommonName('area', c.area_cd) as areaName ,b.po_no ,a.prod_date ,a.item_cd ,d.item_name ,a.order_qty ,t.client_name ,eq.equipment_cd ,eq.equipment_name ,dbo.getCommonName('PROC_STATUS', a.proc_status) as procStatusName ,c.work_order_id ,b.work_batch_id ,a.work_proc_id ,b.make_no from TB_WORK_ORDER_PROC a inner join TB_WORK_ORDER_BATCH b on b.work_batch_id = a.work_batch_id inner join TB_WORK_ORDER_MST c on b.work_order_id = c.work_order_id inner join tb_item_mst d on d.item_cd = a.item_cd left join tb_client_mst t on t.client_id =c.client_id left join tb_equipment_mst eq on eq.equipment_cd = a.work_equipment_Cd where a.proc_cd = 'PRC002' AND a.proc_order_date between #{strDate} and #{endDate} and a.proc_status in ('21','22')
AND c.area_cd = #{areaCd}
and a.item_cd = #{itemCd}
and d.item_name LIKE '%' + #{itemName} + '%'
and t.client_name LIKE '%' + #{clientName} + '%'
ORDER BY c.work_order_date DESC, c.seq DESC

select    count(*) as cnt
from   tb_mat_condition a
where  a.work_proc_id =  #{workProcId}
